-- Minimum Window Substring (Hard)
INSERT INTO coding_problems (slug, title, description, difficulty, category, type, tags, starter_code, test_cases, examples, constraints, points, order_index, time_limit_ms, memory_limit_kb, input_format, output_format, editorial, judged)
VALUES ($q$minimum-window-substring$q$, $q$Minimum Window Substring$q$, $q$Given strings s and t, find the shortest substring of s that contains every character of t, counting repeats (if t has two a's, the window needs at least two a's).

If several windows have the minimum length, print the one that starts earliest. If no window exists, print -1.$q$, $q$Hard$q$, $q$Strings$q$, 'code', ARRAY[$q$string$q$, $q$sliding-window$q$, $q$hash-map$q$, $q$two-pointers$q$]::text[], $q${"python": "import sys\n\n\ndef main():\n    lines = sys.stdin.read().split('\\n')\n    # Input:\n    # Line 1: string s.\n    # Line 2: string t.\n    # TODO: solve, then print the answer\n\n\nmain()\n", "javascript": "const lines = require('fs').readFileSync(0, 'utf8').split('\\n');\n// Input:\n// Line 1: string s.\n// Line 2: string t.\n// TODO: solve, then console.log the answer\n", "java": "import java.io.*;\nimport java.util.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n        List<String> lines = new ArrayList<>();\n        for (String s; (s = in.readLine()) != null; ) lines.add(s);\n        // Input:\n        // Line 1: string s.\n        // Line 2: string t.\n        // TODO: solve, then System.out.println the answer\n    }\n}\n", "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    // Input:\n    // Line 1: string s.\n    // Line 2: string t.\n    // TODO: read with cin / getline, solve, print the answer\n    return 0;\n}\n", "c": "#include <stdio.h>\n\nint main(void) {\n    // Input:\n    // Line 1: string s.\n    // Line 2: string t.\n    /* TODO: read with scanf / fgets, solve, print the answer */\n    return 0;\n}\n"}$q$::jsonb, '[]'::jsonb, $q$[{"input": "adobecodebanc\nabc", "output": "banc", "explanation": "banc is the shortest window containing a, b and c."}, {"input": "a\naa", "output": "-1", "explanation": "s has only one a."}]$q$::jsonb, ARRAY[$q$1 ≤ |s|, |t| ≤ 10 000$q$, $q$Lowercase English letters$q$]::text[], 50, 1020, 2000, 262144, $q$Line 1: string s.
Line 2: string t.$q$, $q$The window itself, or -1.$q$, $q$Count the characters needed from t. Expand the right edge, decreasing a counter 'missing' whenever a needed character is covered. When missing reaches 0, shrink the left edge as far as possible while the window stays valid, and record it if it is strictly shorter than the best so far (strict comparison keeps the earliest window on ties). Each pointer moves at most |s| times: O(|s| + |t|).$q$, false)
ON CONFLICT (slug) DO NOTHING;

